        uint256 fromBefore = _erc20BalanceOf(asset, from);
        uint256 toBefore = _erc20BalanceOf(asset, to);
        _callTransfer(asset, to, amount);
        _assertERC20TransferDelta(asset, from, to, amount, fromBefore, toBefore);
    }

